from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing elements in parallel.

    Uses a thread pool. The output order matches the input order, and an
    empty input yields an empty list.
    """
    with ThreadPoolExecutor() as executor:
        return list(executor.map(square, xs))


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_basic() -> None:
    assert squares([1, 2, 3]) == [1, 4, 9]


def test_squares_negatives() -> None:
    assert squares([-3, 0, 3]) == [9, 0, 9]


def test_squares_preserves_order() -> None:
    xs = list(range(100))
    assert squares(xs) == [x * x for x in xs]
